92	    /**
93	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
94	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
95	     */
96	    private static final Map<String, String> CITY_REGION = Map.of(
97	        "Sydney", "NSW",
98	        "Melbourne", "VIC",
99	        "Brisbane", "QLD");
