134	    /**
135	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
136	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
137	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
138	     * split by taking its leading digit as the (minimal) country code.
139	     */
140	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
141	
142	    /**
143	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
144	     * single space, then the national digits grouped in threes from the left (e.g. the stored
145	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
146	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
147	     * digit string.
148	     *
149	     * @return the human-readable telephone, or the stored value when it cannot be formatted
150	     */
151	    public String getTelephoneDisplay() {
152	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
153	            return this.telephone;
154	        }
155	        String digits = this.telephone.substring(1);
156	        String countryCode = extractCountryCode(digits);
157	        String national = digits.substring(countryCode.length());
158	        StringBuilder display = new StringBuilder("+").append(countryCode);
159	        for (int i = 0; i < national.length(); i += 3) {
160	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
161	        }
162	        return display.toString();
163	    }
164	
165	    /**
166	     * Splits the country code off an E.164 digit string (country code followed by national digits,
167	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
168	     * whose required national-number length matches the remaining digits is preferred; failing that,
169	     * the leading digit is used as the country code.
170	     *
171	     * @param digits the E.164 digits without the leading {@code '+'}
172	     * @return the country-code portion of {@code digits}
173	     */
174	    private static String extractCountryCode(String digits) {
175	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
176	            String code = entry.getKey();
177	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
178	                return code;
179	            }
180	        }
181	        return digits.substring(0, 1);
182	    }
