208	    /**
209	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
210	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
211	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
212	     * elapsed from the birth date to the registration date (defaulting to the server's current date
213	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
214	     *
215	     * @return the age band, or {@code null} when the birth date is absent
216	     */
217	    public String getAgeBand() {
218	        if (this.birthDate == null) {
219	            return null;
220	        }
221	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
222	        int years = Period.between(this.birthDate, asAt).getYears();
223	        if (years < 18) {
224	            return "MINOR";
225	        }
226	        if (years < 65) {
227	            return "ADULT";
228	        }
229	        return "SENIOR";
230	    }
