610	        for (Pet pet : getPetsInternal()) {
611	            if (!ignoreNew || !pet.isNew()) {
612	                String compName = pet.getName();
613	                compName = compName.toLowerCase();
614	                if (compName.equals(name)) {
615	                    return pet;
616	                }
617	            }
618	        }
619	        return null;
620	    }
